/* Fictional browser-local photo posting; production access is checked by PHP. */
(function(root){'use strict';const R=root.Reunion;
function prepare(s){s.albums.forEach(a=>{if(a.name==='思い出アルバム')a.name='フォトアルバム';});if(!s.albums.some(a=>a.purpose==='submissions'))s.albums.push({id:Math.max(0,...s.albums.map(a=>a.id))+1,name:'みんなの投稿写真',description:'最近の一枚や、身近な風景。みんなの写真とコメントをどうぞ。',position:50,visible:true,purpose:'submissions'});if(!s.albumPairVersion){const before=R.clone(s.albums),main=s.albums.find(a=>a.name==='卒業アルバム'&&a.purpose!=='submissions')||s.albums.find(a=>a.purpose!=='submissions'),posts=s.albums.find(a=>a.purpose==='submissions');if(main&&posts){s.albumPairBackup={albums:before,photos:s.photos.map(p=>({id:p.id,albumId:p.albumId,published:p.published}))};s.photos.forEach(p=>{if(before.find(a=>a.id===p.albumId)?.visible===false)p.published=false;p.albumId=p.submitted||p.albumId===posts.id?posts.id:main.id;});Object.assign(main,{name:'卒業アルバム',description:'懐かしい卒業の思い出を、ここに。',position:1,visible:true});Object.assign(posts,{name:'みんなの投稿写真',position:2,visible:true});s.albums=[main,posts];s.photos.forEach(p=>p.album=s.albums.find(a=>a.id===p.albumId)?.name||'');R.audit(s,'システム（サンプル）','アルバムを2つに整理','albums',before,s.albums,'ユーザー指定。写真・投稿・コメントを保持。');s.albumPairVersion=1;}}s.photos.forEach(p=>{p.deleted??=false;p.sortOrder??=0;p.caption??='';p.authorLabel??='';});}
function album(s){return s.albums.find(a=>a.purpose==='submissions');}
function member(s,uid){const u=s.people.find(p=>p.id===uid);if(!u||!R.active(u))throw new Error('参加予定として登録している方が投稿できます。');if(s.settings.clock>s.settings.photoEnd)throw new Error('写真の公開・投稿期間が終了しています。');if(!album(s)?.visible)throw new Error('現在、投稿アルバムの受付を停止しています。');return u;}
function admin(s,uid){const u=s.people.find(p=>p.id===uid);if(!u||!['owner','organizer'].includes(u.role))throw new Error('幹事のログインが必要です。');return u;}
function text(d){const title=String(d.title||'').trim(),caption=String(d.caption||'').trim(),authorLabel=String(d.author||'').trim();if(!title||title.length>200||caption.length>1000||!authorLabel||authorLabel.length>100)throw new Error('タイトル（200文字）・投稿者名（100文字）・コメント（1000文字）を確認してください。');return {title,caption,authorLabel};}
function snapshot(p){return Object.fromEntries(['id','title','caption','authorLabel','albumId','sortOrder','published','deleted','ownerId'].map(k=>[k,p[k]]));}
function reason(d){if(!String(d.reason||'').trim())throw new Error('処理理由を入力してください。');return String(d.reason).trim();}
function submit(s,d,image,uid){prepare(s);const u=member(s,uid),t=text(d);if(d.consent!=='yes')throw new Error('掲載の同意にチェックしてください。');if(!d.postKey)throw new Error('投稿画面を再読み込みしてください。');const old=s.photos.find(p=>p.postKey===d.postKey);if(old){if(old.ownerId!==uid)throw new Error('投稿画面を再読み込みしてください。');return old;}if(s.photos.filter(p=>p.submitted&&p.ownerId===uid).length>=50)throw new Error('1人50枚まで投稿できます。');if(!image?.src?.startsWith('data:image/jpeg;base64,'))throw new Error('JPEG／PNGの写真を選択してください。');const a=album(s),p={...t,src:image.src,id:Math.max(0,...s.photos.map(p=>p.id))+1,ownerId:uid,postKey:d.postKey,albumId:a.id,album:a.name,created:new Date().toISOString(),submitted:true,published:true,deleted:false,sortOrder:0,sample:false};s.photos.push(p);R.audit(s,u.name,'参加者の写真投稿','photo:'+p.id,null,snapshot(p),'本人の掲載同意・自動掲載');return p;}
function edit(s,id,d,uid){const u=admin(s,uid),p=s.photos.find(p=>p.id===id&&!p.deleted),t=text(d),a=s.albums.find(a=>a.id===Number(d.albumId)),order=Number(d.sortOrder),why=reason(d);if(!p||!a||!Number.isInteger(order)||order<0||order>999999)throw new Error('写真・アルバム・表示順（0〜999999）を確認してください。');const before=snapshot(p);Object.assign(p,t,{albumId:a.id,album:a.name,sortOrder:order,published:d.published==='yes'});R.audit(s,u.name,'写真・コメントを編集','photo:'+id,before,snapshot(p),why);}
function remove(s,id,why,uid){const u=admin(s,uid),p=s.photos.find(p=>p.id===id&&!p.deleted);if(!p)throw new Error('掲載中の写真がありません。');const r=reason({reason:why}),before=snapshot(p);p.deleted=true;p.published=false;R.audit(s,u.name,'写真を削除（取り下げ）','photo:'+id,before,snapshot(p),r);}
function restore(s,id,why,uid){const u=admin(s,uid),p=s.photos.find(p=>p.id===id&&p.deleted);if(!p)throw new Error('削除済みの写真がありません。');const r=reason({reason:why}),before=snapshot(p);p.deleted=false;p.published=false;R.audit(s,u.name,'写真を非公開で復元','photo:'+id,before,snapshot(p),r);}
function sorted(photos){return photos.filter(p=>!p.deleted).slice().sort((a,b)=>(a.sortOrder||0)-(b.sortOrder||0)||String(b.created||'').localeCompare(a.created||'')||b.id-a.id);}
const P={prepare,album,member,submit,edit,remove,restore,sorted};root.PhotoPosts=P;if(typeof module!=='undefined')module.exports=P;
})(typeof globalThis!=='undefined'?globalThis:this);
